32	## 二、你需要产出的数据结构
33	
34	```c
35	// ── 定义在 api/behavior.h，你来实现 ──
36	
37	typedef enum { 
38	    FOCUSED,          // 专注学习
39	    GLANCING_PHONE,   // 短暂看手机 (不提醒)
40	    PLAYING_PHONE,    // 玩手机 (提醒)
41	    AWAY,             // 离座
42	    DROWSY            // 低头/瞌睡
43	} status_t;
44	
45	typedef enum { 
46	    NONE,             // 不需要行动
47	    REMIND,           // 触发提醒 (严格:警告 / 鼓励:关怀)
48	    ENCOURAGE         // 触发鼓励 (仅鼓励模式, 专注里程碑)
49	} action_t;
50	
51	typedef struct {
52	    status_t  status;              // 当前学习状态
53	    action_t  action;              // 应采取的行动
54	    char      message[128];        // 提醒/鼓励文字 (★ 郭黄亦昕直接显示)
55	    bool      milestone_reached;   // 是否达到专注里程碑
56	    int       milestone_minutes;   // 连续专注分钟数
57	    int       focus_score_delta;   // 评分变化量 (正=加分, 负=扣分)
58	} study_state_t;
59	
60	
61	// ── 你需要实现的 3 个函数 ──
62	
63	// 初始化, 设置当前模式
64	void behavior_init(int mode);  // mode: 0=STRICT, 1=GENTLE
65	
66	// 核心函数: 消费 Observation 历史 → 输出行为状态
67	// 万思源在 wifi_task 每收到一个新 Observation 后调用一次
68	// 返回: study_state_t (由调用方通过 mq 分发给状态机和 UI)
69	study_state_t behavior_analyze(void);
70	
71	// 切换模式 (运行时用户通过按键切换)
72	void behavior_set_mode(int mode);
