76	
77	## 三、你需要做的三件事
78	
79	### 3.1 时序状态判定引擎
80	
81	核心思路：从 Observation 历史中提取**持续时间**和**变化趋势**，而不是看单帧快照。
82	
83	```c
84	study_state_t behavior_analyze(void) {
85	    // 1. 从周礼航获取 Observation 历史
86	    observation_t hist[60];
87	    int n = perception_get_history(hist, 60);
88	    if (n < 1) {
89	        // 没有数据, 返回前一次的状态
90	        return previous_state;
91	    }
92	    
93	    observation_t *latest = &hist[n - 1];
94	    
95	    // 2. 离座判定
96	    //    统计最近 15 秒内 person_present=false 的帧数
97	    int away_frames = count_false_in_window(hist, n, person_present, 15000);
98	    if (away_frames >= 2) {  // 15s 内至少 2 帧无人 (约 30s 确认)
99	        int away_sec = calc_duration(hist, n, 
100	                        cfg.away_threshold_sec * 1000);
101	        if (away_sec >= cfg.away_threshold_sec) {
102	            return build_state(AWAY, REMIND);
103	        }
104	    }
105	    
106	    // 3. 手机分心判定 (区分玩手机 vs 看手机)
107	    if (latest->phone_detected && latest->phone_near_hand) {
108	        // 计算手机持续存在的时间
109	        int phone_sec = calc_continuous_duration(hist, n, 
110	                         phone_detected);
111	        // 计算手部平均运动量
112	        float motion = calc_avg_in_window(hist, n, 
113	                        hand_motion_score, phone_sec * 1000);
114	        
115	        if (phone_sec >= cfg.phone_playing_sec && motion > 0.3) {
116	            return build_state(PLAYING_PHONE, REMIND);
117	        } else if (phone_sec >= cfg.phone_glance_sec) {
118	            return build_state(GLANCING_PHONE, NONE);
119	        }
120	    }
121	    
122	    // 4. 瞌睡判定
123	    if (latest->head_pitch > cfg.head_pitch_max) {
124	        int drowsy_sec = calc_continuous_duration(hist, n,
125	                          head_pitch, cfg.head_pitch_max);
126	        if (drowsy_sec >= cfg.drowsy_threshold_sec) {
127	            return build_state(DROWSY, REMIND);
128	        }
129	    }
130	    
131	    // 5. 专注里程碑检测 (鼓励模式专属)
132	    if (current_mode == MODE_GENTLE && cfg.enable_milestone) {
133	        int streak = calc_focus_streak_minutes(hist, n);
134	        if (streak >= cfg.focus_milestone_min && 
135	            streak % cfg.focus_milestone_min == 0) {
136	            // 避免同一里程碑重复触发
137	            if (streak > last_celebrated_streak) {
138	                last_celebrated_streak = streak;
139	                return build_state(FOCUSED, ENCOURAGE);
140	            }
141	        }
142	    }
143	    
144	    // 6. 专注状态 (默认)
145	    return build_state(FOCUSED, NONE);
146	}
147	```
148	
149	### 3.2 严格模式 vs 鼓励模式
150	
151	**所有差异集中在配置表 + 话术表**，分析引擎代码完全共用：
152	
153	```c
154	// ═══════════ 模式配置表 ═══════════
155	
156	typedef struct {
