160	    int  drowsy_threshold_sec;   // 瞌睡判定阈值
161	    int  remind_cooldown_sec;    // 两次提醒最小间隔
162	    int  remind_after_n_times;   // 累计 N 次分心才提醒一次
163	    int  focus_milestone_min;    // 专注里程碑间隔 (0=禁用)
