225	### 3.3 构建输出状态
226	
227	```c
228	study_state_t build_state(status_t s, action_t a) {
229	    study_state_t st = { .status = s, .action = a };
230	    
231	    if (a == REMIND) {
232	        // 提醒冷却检查
233	        if (elapsed_since(last_remind_time) < cfg->remind_cooldown_sec * 1000)
234	            st.action = NONE;  // 冷却中, 不提醒
235	        
236	        // 累计次数检查 (鼓励模式)
237	        if (cfg->remind_after_n_times > 1) {
238	            distraction_since_last_remind++;
239	            if (distraction_since_last_remind < cfg->remind_after_n_times)
240	                st.action = NONE;
241	            else
242	                distraction_since_last_remind = 0;
243	        }
244	        
245	        if (st.action == REMIND) {
246	            last_remind_time = now_ms();
247	            snprintf(st.message, sizeof(st.message), "%s", cfg->msgs[s]);
248	            st.focus_score_delta = get_penalty(s);
249	        }
250	    }
251	    
252	    if (a == ENCOURAGE) {
253	        snprintf(st.message, sizeof(st.message), 
254	                 "已专注学习 %d 分钟, 继续保持!", 
255	                 last_celebrated_streak);
256	        st.milestone_reached = true;
257	        st.milestone_minutes = last_celebrated_streak;
258	        st.focus_score_delta = cfg->score_bonus_milestone;
259	    }
260	    
261	    return st;
262	}
263	
264	int get_penalty(status_t s) {
265	    switch (s) {
266	        case PLAYING_PHONE: return cfg->score_penalty_phone;
267	        case AWAY:          return cfg->score_penalty_away;
268	        case DROWSY:        return cfg->score_penalty_drowsy;
269	        default:            return 0;
270	    }
271	}
272	```
