      if (read(fd, &sample, sizeof(sample)) == sizeof(sample))
        {
          if (sample != 0)
            {
              press_count++;
              printf("  [事件] 按下, 掩码=0x%02x\n", sample);
            }
          else
            {
              rel_count++;
            }
        }

      timeout_ms -= 200;
    }

  close(fd);

  if (press_count > 0)
    {
      TEST_PASS("检测到 %d 次按键按下 (%d 次释放)", press_count, rel_count);
      return OK;
    }
  else
    {
      TEST_FAIL("15 秒内未检测到任何按键");
      return ERROR;
    }
}

