int main(int argc, char *argv[])
{
  const char *want = NULL;
  int i;
  int rc;

  printf("\n");
  printf("==================================================\n");
  printf("  FOCUS AIoT 设备硬件验证测试\n");
  printf("  板卡: ESP32-S3-EYE (openvela)\n");
  printf("==================================================\n");

  if (argc > 1)
    {
      want = argv[1];
    }

  if (want == NULL || strcmp(want, "all") == 0)
    {
      for (i = 0; i < (int)NTESTS; i++)
        {
          g_tests[i].func();
        }
    }
  else
    {
      for (i = 0; i < (int)NTESTS; i++)
        {
          if (strcmp(want, g_tests[i].name) == 0)
            {
              g_tests[i].func();
              goto done;
            }
        }

      print_usage(argv[0]);
      return EXIT_FAILURE;
    }

done:
  printf("\n==================================================\n");
  printf("  汇总: %d 通过, %d 失败\n", g_tests_pass, g_tests_fail);
  if (g_tests_fail == 0)
    {
      printf("  所有硬件测试通过!\n");
    }
  else
    {
      printf("  存在失败项, 请根据上方日志排查。\n");
    }

  printf("==================================================\n");
  rc = g_tests_fail == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
  return rc;
}

/****************************************************************************
 * FOCUS AIoT - 设备硬件验证测试 (Device Hardware Validation)
 *
 * 在 openvela + ESP32-S3-EYE 上逐项验证外设可用性：
 *   - LCD  (framebuffer  /dev/fb0)
 *   - LED  (power LED   /dev/userleds)
 *   - 按键  (BOOT button /dev/buttons)
 *   - 摄像头 (OV2640     /dev/video0)
 *   - 加速度计 (QMA7981  /dev/accel0)
 *   - SD 卡 (/dev/mmcsd1 存在性)
 *
 * 用法 (NSH):
 *   hello_app            # 运行全部测试
 *   hello_app all        # 同上
 *   hello_app lcd|led|button|camera|accel|sd   # 单测某一项
 *
 * 每个测试结束都会打印 PASS/FAIL 和原因，全部跑完后打印汇总。
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>

#include <nuttx/video/fb.h>
#include <nuttx/leds/userled.h>
#include <nuttx/input/buttons.h>
#include <nuttx/sensors/qma7981.h>
#include <sys/videoio.h>

#define DEV_FB       "/dev/fb0"
#define DEV_LED      "/dev/userleds"
#define DEV_BUTTONS  "/dev/buttons"
#define DEV_CAMERA   "/dev/video0"
#define DEV_ACCEL    "/dev/accel0"
#define DEV_SD       "/dev/mmcsd1"

/* ---- 测试结果统计 ---- */
static int g_tests_pass = 0;
static int g_tests_fail = 0;

#define TEST_BEGIN(name) \
  do { printf("\n===== [TEST] %s =====\n", (name)); } while (0)

#define TEST_PASS(fmt, ...) \
  do { printf("  [PASS] " fmt "\n", ##__VA_ARGS__); g_tests_pass++; } while (0)

#define TEST_FAIL(fmt, ...) \
  do { printf("  [FAIL] " fmt "\n", ##__VA_ARGS__); g_tests_fail++; } while (0)

/* ================= LCD framebuffer 测试 ================= */

static int test_lcd(void)
{
  int fd;
  int ret;
  uint16_t *fbmem;
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  struct fb_area_s area;
  fb_coord_t x, y;
  size_t i;

  TEST_BEGIN("LCD (/dev/fb0)");

  fd = open(DEV_FB, O_RDWR);
  if (fd < 0)
    {
      TEST_FAIL("open %s failed: %d (%s)", DEV_FB, errno, strerror(errno));
      return ERROR;
    }

  ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)((uintptr_t)&vinfo));
  if (ret < 0)
    {
      TEST_FAIL("FBIOGET_VIDEOINFO failed: %d", errno);
      close(fd);
      return ERROR;
    }

  printf("  info: %ux%u, nplanes=%u, fmt=%u\n",
         vinfo.xres, vinfo.yres, vinfo.nplanes, vinfo.fmt);

  ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)&pinfo));
  if (ret < 0)
    {
      TEST_FAIL("FBIOGET_PLANEINFO failed: %d", errno);
      close(fd);
      return ERROR;
    }

  printf("  plane: bpp=%u stride=%u fblen=%zu\n",
         pinfo.bpp, pinfo.stride, pinfo.fblen);

  if (pinfo.bpp != 16)
    {
      TEST_FAIL("unsupported bpp %u (expected 16, RGB565)", pinfo.bpp);
      close(fd);
      return ERROR;
    }

  fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
               MAP_SHARED | MAP_FILE, fd, 0);
  if (fbmem == MAP_FAILED)
    {
      TEST_FAIL("mmap failed: %d", errno);
      close(fd);
      return ERROR;
    }

  /* 依次填充 5 条横带: 红 / 绿 / 蓝 / 白 / 黑 */
  {
    static const uint16_t colors[5] =
      { 0xF800, 0x07E0, 0x001F, 0xFFFF, 0x0000 };
    static const char *cname[5] =
      { "RED", "GREEN", "BLUE", "WHITE", "BLACK" };
    int band;

    for (band = 0; band < 5; band++)
      {
        for (y = (fb_coord_t)(band * vinfo.yres / 5);
             y < (fb_coord_t)((band + 1) * vinfo.yres / 5);
             y++)
          {
            uint16_t *row = (uint16_t *)((uint8_t *)fbmem + y * pinfo.stride);
            for (x = 0; x < vinfo.xres; x++)
              {
                row[x] = colors[band];
              }
          }

        printf("  filled %s band (y=%u..%u)\n",
               cname[band], band * vinfo.yres / 5,
               (band + 1) * vinfo.yres / 5);
      }
  }

#ifdef CONFIG_FB_UPDATE
  area.x = 0;
  area.y = 0;
  area.w = vinfo.xres;
  area.h = vinfo.yres;
  ret = ioctl(fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&area));
  if (ret < 0)
    {
      TEST_FAIL("FBIO_UPDATE failed: %d", errno);
    }
#endif

  /* 逐像素校验: 采样若干点确认 framebuffer 可写 */
  {
    size_t samples = 0;
    for (i = 0; i < 100; i++)
      {
        size_t off = (i * 97) % (vinfo.xres * vinfo.yres);
        if (fbmem[off] != 0xFFFF)
          {
            samples++;
          }
      }

    if (samples == 0)
      {
        TEST_FAIL("framebuffer 读回全为 0xFFFF, 写入可能未生效");
      }
    else
      {
        TEST_PASS("framebuffer 写入生效, %d/%d 采样点非白, 应显示色带",
                  (int)samples, 100);
      }
  }

  munmap(fbmem, pinfo.fblen);
  close(fd);
  return OK;
}

/* ================= LED 测试 ================= */

static int test_led(void)
{
  int fd;
  int ret;
  uint32_t supported = 0;
  int i;

  TEST_BEGIN("LED (/dev/userleds)");

  fd = open(DEV_LED, O_WRONLY);
  if (fd < 0)
    {
      TEST_FAIL("open %s failed: %d (%s)", DEV_LED, errno, strerror(errno));
      return ERROR;
    }

  ret = ioctl(fd, ULEDIOC_SUPPORTED, (unsigned long)((uintptr_t)&supported));
  if (ret < 0)
    {
      TEST_FAIL("ULEDIOC_SUPPORTED failed: %d", errno);
      close(fd);
      return ERROR;
    }

  printf("  supported LED mask: 0x%08x\n", supported);

  /* 闪烁 5 次, 每次间隔 400ms, 观察电源 LED */
  for (i = 0; i < 5; i++)
    {
      ioctl(fd, ULEDIOC_SETALL, (unsigned long)supported);
      usleep(400 * 1000);
      ioctl(fd, ULEDIOC_SETALL, (unsigned long)0);
      usleep(400 * 1000);
    }

  /* 最后保持点亮, 方便观察 */
  ioctl(fd, ULEDIOC_SETALL, (unsigned long)supported);
  printf("  LED 已闪烁 5 次并保持点亮, 请观察板载电源 LED\n");

  TEST_PASS("LED 控制完成 (请人工确认闪烁/点亮)");
  close(fd);
  return OK;
}

/* ================= 按键测试 ================= */

static int test_button(void)
{
  int fd;
  int ret;
  btn_buttonset_t supported = 0;
  struct pollfd fds;
  int timeout_ms = 15000;   /* 等待按键 15 秒 */
  int press_count = 0;
  int rel_count = 0;

  TEST_BEGIN("BUTTON (/dev/buttons)");

  fd = open(DEV_BUTTONS, O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      TEST_FAIL("open %s failed: %d (%s)", DEV_BUTTONS, errno, strerror(errno));
      return ERROR;
    }

  ret = ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)((uintptr_t)&supported));
  if (ret < 0)
    {
      TEST_FAIL("BTNIOC_SUPPORTED failed: %d", errno);
      close(fd);
      return ERROR;
    }

  printf("  supported button mask: 0x%02x\n", supported);
  printf("  请在 %d 秒内按压 BOOT 按键数次...\n", timeout_ms / 1000);

  fds.fd = fd;
  fds.events = POLLIN;

  while (timeout_ms > 0)
    {
      int pv;
      btn_buttonset_t sample = 0;

      pv = poll(&fds, 1, timeout_ms);
      if (pv < 0)
        {
          TEST_FAIL("poll failed: %d", errno);
          close(fd);
          return ERROR;
        }
      if (pv == 0)
        {
          break;  /* 超时 */
        }

      if (read(fd, &sample, sizeof(sample)) == sizeof(sample))
        {
          if (sample != 0)
            {
              press_count++;
              printf("  [事件] 按下, 掩码=0x%02x\n", sample);
            }
          else
            {
              rel_count++;
            }
        }

      timeout_ms -= 200;
    }

  close(fd);

  if (press_count > 0)
    {
      TEST_PASS("检测到 %d 次按键按下 (%d 次释放)", press_count, rel_count);
      return OK;
    }
  else
    {
      TEST_FAIL("15 秒内未检测到任何按键");
      return ERROR;
    }
}

/* ================= 摄像头测试 ================= */

#define CAM_WIDTH     320
#define CAM_HEIGHT    240
#define CAM_BUFFERS   2
#define CAM_BUFSIZE   (CAM_WIDTH * CAM_HEIGHT * 2)  /* RGB565 全尺寸, JPEG 更小 */
#define CAM_FRAMES    3

static int test_camera(void)
{
  int fd;
  int ret;
  int i;
  v4l2_format_t fmt;
  v4l2_requestbuffers_t req;
  v4l2_buffer_t buf;
  v4l2_buf_type_t type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  uint8_t *buffers[CAM_BUFFERS];
  int got_frames = 0;

  TEST_BEGIN("CAMERA (/dev/video0)");

  memset(buffers, 0, sizeof(buffers));

  fd = open(DEV_CAMERA, O_RDWR);
  if (fd < 0)
    {
      TEST_FAIL("open %s failed: %d (%s)", DEV_CAMERA, errno, strerror(errno));
      return ERROR;
    }

  /* 设置 JPEG 输出格式 */
  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = type;
  fmt.fmt.pix.width       = CAM_WIDTH;
  fmt.fmt.pix.height      = CAM_HEIGHT;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;

  ret = ioctl(fd, VIDIOC_S_FMT, (unsigned long)((uintptr_t)&fmt));
  if (ret < 0)
    {
      TEST_FAIL("VIDIOC_S_FMT failed: %d (%s)", errno, strerror(errno));
      close(fd);
      return ERROR;
    }

  /* 申请用户指针缓冲区 */
  memset(&req, 0, sizeof(req));
  req.type   = type;
  req.memory = V4L2_MEMORY_USERPTR;
  req.count  = CAM_BUFFERS;
  req.mode   = V4L2_BUF_MODE_FIFO;

  ret = ioctl(fd, VIDIOC_REQBUFS, (unsigned long)((uintptr_t)&req));
  if (ret < 0)
    {
      TEST_FAIL("VIDIOC_REQBUFS failed: %d (%s)", errno, strerror(errno));
      close(fd);
      return ERROR;
    }

  for (i = 0; i < CAM_BUFFERS; i++)
    {
      buffers[i] = memalign(32, CAM_BUFSIZE);
      if (!buffers[i])
        {
          TEST_FAIL("分配摄像头缓冲区失败 (第 %d 个)", i);
          goto out_free;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type     = type;
      buf.memory   = V4L2_MEMORY_USERPTR;
      buf.index    = i;
      buf.m.userptr = (unsigned long)(uintptr_t)buffers[i];
      buf.length   = CAM_BUFSIZE;

      ret = ioctl(fd, VIDIOC_QBUF, (unsigned long)((uintptr_t)&buf));
      if (ret < 0)
        {
          TEST_FAIL("VIDIOC_QBUF failed: %d (%s)", errno, strerror(errno));
          goto out_free;
        }
    }

  /* 开始取流 */
  ret = ioctl(fd, VIDIOC_STREAMON, (unsigned long)(uintptr_t)&type);
  if (ret < 0)
    {
      TEST_FAIL("VIDIOC_STREAMON failed: %d (%s)", errno, strerror(errno));
      goto out_free;
    }

  printf("  正在采集 %d 帧 JPEG (320x240)...\n", CAM_FRAMES);

  for (i = 0; i < CAM_FRAMES; i++)
    {
      memset(&buf, 0, sizeof(buf));
      buf.type   = type;
      buf.memory = V4L2_MEMORY_USERPTR;

      ret = ioctl(fd, VIDIOC_DQBUF, (unsigned long)((uintptr_t)&buf));
      if (ret < 0)
        {
          TEST_FAIL("VIDIOC_DQBUF 失败 (第 %d 帧): %d (%s)",
                    i, errno, strerror(errno));
          break;
        }

      printf("  frame %d: %u bytes\n", i, buf.bytesused);
      got_frames++;

      /* 归还缓冲区 */
      ret = ioctl(fd, VIDIOC_QBUF, (unsigned long)((uintptr_t)&buf));
      if (ret < 0)
        {
          TEST_FAIL("归还缓冲区失败: %d", errno);
          break;
        }

      usleep(300 * 1000);
    }

  ioctl(fd, VIDIOC_STREAMOFF, (unsigned long)(uintptr_t)&type);

  if (got_frames >= 1)
    {
      TEST_PASS("采集到 %d 帧, 帧大小如上 (应 >0 且接近 JPEG 实际大小)",
                got_frames);
    }
  else
    {
      TEST_FAIL("未采集到有效帧");
    }

out_free:
  for (i = 0; i < CAM_BUFFERS; i++)
    {
      free(buffers[i]);
    }

  close(fd);
  return got_frames >= 1 ? OK : ERROR;
}

