/****************************************************************************
 * FOCUS AIoT - 视觉感知模块接口 (api/perception.h)
 *
 * 负责人: 周礼航
 * 职责: 从 JPEG 图片中提取统一 Observation (单帧空间分析)。
 *       云端 API 调用、去抖稳定、历史管理都在本模块内完成。
 *       不区分严格/鼓励模式，不判断行为。
 *
 * 冻结: observation_t 字段、3 个函数签名。
 *       后续只能追加 observation_t 字段，不得删除或重命名已有字段。
 ****************************************************************************/

#ifndef FOCUS_AIOT_API_PERCEPTION_H
#define FOCUS_AIOT_API_PERCEPTION_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- observation_t: 单帧视觉感知结果 ---- */

typedef struct {
    /* 人体检测 */
    bool     person_present;       /* 画面中是否有人 */
    float    person_bbox[4];       /* 人体边界框 (x,y,w,h) 归一化 [0-1] */

    /* 手机检测 */
    bool     phone_detected;       /* 是否检测到手机 */
    bool     phone_near_hand;      /* 手机是否在手部区域 */

    /* 头部姿态 (度, 负=低头 正=仰头) */
    float    head_pitch;
    float    head_yaw;

    /* 手部运动量 [0-1] */
    float    hand_motion_score;

    /* 整体置信度 [0-1] */
    float    confidence;

    /* 时间戳 (毫秒, 自系统启动计) */
    uint32_t timestamp_ms;

    /* === 保留扩展字段 (>= v2 追加) === */
    uint8_t  _reserved[16];
} observation_t;

/* ---- 接口函数 ---- */

/* 初始化: 配置云端 API URL/Key。
 * 返回: 0=成功 */
int  perception_init(const char *api_url, const char *api_key);

/* 核心: 拿一张 JPEG → 调云端 API → 去抖 → 输出一个 observation_t。
 * jpeg / jpeg_len: 输入图像数据 (可来自真实摄像头或 mock 缓冲区)
 * out:             输出的 Observation
 * 超时 ≤6s，失败返回错误码 (不崩)。
 * 返回: 0=成功, FOCUS_ERR_PERCEP_TIMEOUT / FOCUS_ERR_PERCEP_JSON */
int  perception_process(uint8_t *jpeg, size_t jpeg_len, observation_t *out);

/* 获取最近 N 个 Observation (从旧到新排列)。
 * buf: 输出缓冲区 (调用方分配, 至少 n * sizeof(observation_t))
 * n:   最多返回条数
 * 返回: 实际返回条数 (≤ n) */
int  perception_get_history(observation_t *buf, int n);

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_API_PERCEPTION_H */

/****************************************************************************
 * FOCUS AIoT - 行为分析模块接口 (api/behavior.h)
 *
 * 负责人: 赵思涵
 * 职责: 从 Observation 时间序列中推理学习状态，严格/鼓励双模式引擎。
 *       pure function: 不访问网络、不操作硬件、10ms 内返回。
 *
 * 冻结: status_t / action_t / study_state_t / 3 个函数签名。
 *       mode_config_t 由行为模块内部管理 (见 config/behavior_config.h)。
 ****************************************************************************/

#ifndef FOCUS_AIOT_API_BEHAVIOR_H
#define FOCUS_AIOT_API_BEHAVIOR_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- 学习状态枚举 ---- */

typedef enum {
    FOCUSED,          /* 专注学习               */
    GLANCING_PHONE,   /* 短暂看手机 (不提醒)     */
    PLAYING_PHONE,    /* 玩手机 (提醒)           */
    AWAY,             /* 离座                    */
    DROWSY            /* 低头/瞌睡               */
} status_t;

/* ---- 行动类型 ---- */

typedef enum {
    NONE,             /* 不需要行动              */
    REMIND,           /* 触发提醒 (严格:警告 / 鼓励:关怀) */
    ENCOURAGE         /* 触发鼓励 (仅鼓励模式, 专注里程碑) */
} action_t;

/* ---- study_state_t: 行为分析输出 ---- */

typedef struct {
    status_t  status;              /* 当前学习状态            */
    action_t  action;              /* 应采取的行动            */
    char      message[128];        /* 提醒/鼓励文字
                                    * ★ 郭黄亦昕直接显示此文本，
                                    *   不自行生成文案       */
    bool      milestone_reached;   /* 是否达到专注里程碑
                                    * (仅鼓励模式)           */
    int       milestone_minutes;   /* 连续专注分钟数          */
    int       focus_score_delta;   /* 评分变化量
                                    * (正=加分, 负=扣分, 增量) */
} study_state_t;

/* ---- 接口函数 ---- */

/* 初始化，设置当前模式。
 * mode: 0=MODE_STRICT, 1=MODE_GENTLE */
void behavior_init(int mode);

/* 核心函数: 消费 Observation 历史 → 输出行为状态。
 * 纯计算，10ms 内返回。
 * 在 wifi_task 每收到新 Observation 后调用一次。 */
study_state_t behavior_analyze(void);

/* 切换模式 (运行时用户通过按键切换)。
 * 可在监测进行中被调用，不要求重启。 */
void behavior_set_mode(int mode);

/* ---- 模式常量 ---- */
#define MODE_STRICT  0
#define MODE_GENTLE  1

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_API_BEHAVIOR_H */

/****************************************************************************
 * FOCUS AIoT - 状态机与会话统计接口 (api/state_machine.h)
 *
 * 负责人: 万思源
 * 职责: 4 状态 FSM、多任务调度、会话统计、报告生成。
 *
 * 冻结: device_status_t / session_stats_t / 函数签名。
 ****************************************************************************/

#ifndef FOCUS_AIOT_API_STATE_MACHINE_H
#define FOCUS_AIOT_API_STATE_MACHINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- 设备状态 (4 状态 FSM) ---- */

typedef enum {
    DEVICE_IDLE,          /* 待机                    */
    DEVICE_MODE_SELECT,   /* 选择模式 (严格/鼓励)    */
    DEVICE_MONITORING,    /* 监测中                  */
    DEVICE_REPORT         /* 报告页                  */
} device_status_t;

/* ---- 会话统计数据 ---- */

typedef struct {
    uint32_t session_start;          /* 学习开始时间戳 (ms)     */
    uint32_t total_duration_sec;     /* 总时长 (秒)             */
    uint32_t effective_duration_sec; /* 有效学习时长 (秒)       */
    uint8_t  distraction_count;      /* 分心总次数              */
    uint8_t  focus_score;            /* 专注度评分 0-100        */
    uint8_t  current_mode;           /* 0=STRICT, 1=GENTLE     */
    /* --- v2 追加 --- */
    uint8_t  _reserved[32];
} session_stats_t;

/* ---- 接口函数 ---- */

/* 初始化状态机 (进入 IDLE)。 */
void state_machine_init(void);

/* 每个主循环 tick 调用一次 (约 100Hz)。
 * 内部: 轮询按键、消费 study_state_t、更新统计、驱动 UI 刷新。
 * 必须在 20ms 内返回。 */
void state_machine_tick(void);

/* 获取当前设备状态 (供 UI 查询)。 */
device_status_t state_machine_get_status(void);

/* 获取当前会话统计 (供 UI 查询)。 */
const session_stats_t *state_machine_get_stats(void);

/* 获取当前模式。 */
int state_machine_get_mode(void);

/* 获取是否暂停中。 */
bool state_machine_is_paused(void);

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_API_STATE_MACHINE_H */

