79	    }
80	
81	  ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)((uintptr_t)&vinfo));
82	  if (ret < 0)
83	    {
84	      TEST_FAIL("FBIOGET_VIDEOINFO failed: %d", errno);
85	      close(fd);
