87	    }
88	
89	  printf("  info: %ux%u, nplanes=%u, fmt=%u\n",
90	         vinfo.xres, vinfo.yres, vinfo.nplanes, vinfo.fmt);
91	
92	  ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)&pinfo));
93	  if (ret < 0)
94	    {
95	      TEST_FAIL("FBIOGET_PLANEINFO failed: %d", errno);
96	      close(fd);
97	      return ERROR;
98	    }
99	
100	  printf("  plane: bpp=%u stride=%u fblen=%zu\n",
101	         pinfo.bpp, pinfo.stride, pinfo.fblen);
102	
103	  if (pinfo.bpp != 16)
104	    {
105	      TEST_FAIL("unsupported bpp %u (expected 16, RGB565)", pinfo.bpp);
106	      close(fd);
107	      return ERROR;
108	    }
109	
110	  fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
