122	      { 0xF800, 0x07E0, 0x001F, 0xFFFF, 0x0000 };
123	    static const char *cname[5] =
124	      { "RED", "GREEN", "BLUE", "WHITE", "BLACK" };
125	    int band;
126	
127	    for (band = 0; band < 5; band++)
128	      {
129	        for (y = (fb_coord_t)(band * vinfo.yres / 5);
130	             y < (fb_coord_t)((band + 1) * vinfo.yres / 5);
131	             y++)
132	          {
133	            uint16_t *row = (uint16_t *)((uint8_t *)fbmem + y * pinfo.stride);
134	            for (x = 0; x < vinfo.xres; x++)
135	              {
136	                row[x] = colors[band];
137	              }
