/****************************************************************************
 * FOCUS AIoT - 行为分析配置表 (config/behavior_config.h)
 *
 * 负责人: 赵思涵
 * 职责: 严格/鼓励模式参数表 + 话术表。
 *       所有阈值、冷却、扣分/加分、话术统一在这里管理。
 *
 * 冻结: mode_config_t 结构。参数可以调，字段可以加。
 ****************************************************************************/

#ifndef FOCUS_AIOT_CONFIG_BEHAVIOR_CONFIG_H
#define FOCUS_AIOT_CONFIG_BEHAVIOR_CONFIG_H

#include <stdint.h>
#include <stdbool.h>
#include "api/behavior.h"

#ifdef __cplusplus
extern "C" {
#endif

/* ---- 模式配置结构体 ---- */

typedef struct {
    /* 判定阈值 */
    int  phone_glance_sec;       /* 看手机判定阈值 (秒)    */
    int  phone_playing_sec;      /* 玩手机判定阈值 (秒)    */
    int  away_threshold_sec;     /* 离座判定阈值 (秒)      */
    int  drowsy_threshold_sec;   /* 瞌睡判定阈值 (秒)      */
    int  head_pitch_max;         /* 正常头部俯角上限 (度)   */

    /* 提醒策略 */
    int  remind_cooldown_sec;    /* 两次提醒最小间隔 (秒)   */
    int  remind_after_n_times;   /* 累计 N 次分心才提醒     */

    /* 鼓励模式专属 */
    int  focus_milestone_min;    /* 专注里程碑间隔 (分钟, 0=禁用) */
    bool enable_milestone;       /* 是否启用里程碑鼓励       */

    /* 评分 */
    int  score_penalty_phone;    /* 玩手机扣分              */
    int  score_penalty_away;     /* 离座扣分                */
    int  score_penalty_drowsy;   /* 瞌睡扣分                */
    int  score_bonus_milestone;  /* 专注里程碑加分          */

    /* 话术 */
    const char **messages;       /* 提醒话术表 (status_t 索引) */
} mode_config_t;

/* ---- 话术表 ---- */

extern const char *strict_messages[5];
extern const char *gentle_messages[5];

/* ---- 两套配置 ---- */

extern mode_config_t g_mode_configs[2];  /* [MODE_STRICT] [MODE_GENTLE] */

/* ---- 快捷访问 ---- */

/* 获取当前模式的配置表 (由行为模块维护) */
const mode_config_t *behavior_get_current_config(void);

/* 获取指定模式的配置表 */
const mode_config_t *behavior_get_config(int mode);

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_CONFIG_BEHAVIOR_CONFIG_H */

/****************************************************************************
 * FOCUS AIoT - Mock 数据提供者 (core/mock.h)
 *
 * 职责: 在真实硬件/云端未就绪时，为各模块提供假数据。
 *       每个 mock 函数模拟对应模块的真实输出，使整条链路可独立调试。
 *
 * 使用: #define USE_REAL_* 可用 CMake / Kconfig 控制，默认全部用 mock。
 ****************************************************************************/

#ifndef FOCUS_AIOT_CORE_MOCK_H
#define FOCUS_AIOT_CORE_MOCK_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "api/perception.h"
#include "api/behavior.h"
#include "api/session.h"

#ifdef __cplusplus
extern "C" {
#endif

/* ==================== Mock 摄像头 ==================== */

/* 每 5 秒产生一条假帧事件 (实际无图像数据，只发信号) */
void mock_camera_tick(void);

/* ==================== Mock 感知 ==================== */

/* 初始化 mock 感知 (设置 observation 循环序列) */
void mock_perception_init(void);

/* 输出一个假 observation_t (轮流: FOCUSED/PLAYING_PHONE/AWAY/DROWSY) */
int  mock_perception_process(observation_t *out);

/* ==================== Mock 行为 ==================== */

/* 初始化 mock 行为分析 */
void mock_behavior_init(void);

/* 基于 observation 产生 study_state (直接映射，不做真实时序) */
study_state_t mock_behavior_analyze(const observation_t *obs);

/* ==================== Mock UI ==================== */

/* 打印状态到串口 (替代 LCD 显示) */
void mock_ui_show(void);

/* ==================== Mock 音频 ==================== */

/* 打印提醒文字到串口 (替代真实播放) */
void mock_audio_play(const char *msg);

/* ==================== Mock MiMo ==================== */

/* 用本地模板生成建议 */
int  mock_mimo_get_advice(const session_stats_t *stats,
                          const uint8_t distraction_by_type[4],
                          char *advice_out, size_t max_len);

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_CORE_MOCK_H */

/****************************************************************************
 * FOCUS AIoT - 主控入口 (多任务事件循环骨架)
 *
 * 负责人: 万思源
 *
 * 架构: 单线程事件循环驱动 6 个逻辑 task。
 *   camera_task    → 采集 / mock 帧事件 (每 5s)
 *   perception_task → 消费帧 → observation_t
 *   behavior_task   → 消费 observation → study_state_t
 *   state_machine   → 消费 study_state + 按键 → FSM + 统计
 *   ui_task         → 1Hz 刷新 LCD / 串口日志
 *   audio_task      → 提醒 / 鼓励触发
 *
 * 当前阶段 (MVP): 全部 mock，只验证链路日志。
 * 后续逐步 #define USE_REAL_* 替换真实模块。
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "api/error.h"
#include "api/perception.h"
#include "api/behavior.h"
#include "api/state_machine.h"
#include "api/session.h"
#include "config/behavior_config.h"
#include "core/mock.h"

/* ==================== 模式话术表实现 ==================== */

const char *strict_messages[5] = {
    [PLAYING_PHONE] = "请放下手机!",
    [AWAY]          = "请回到座位!",
    [DROWSY]        = "请注意坐姿!",
};

const char *gentle_messages[5] = {
    [PLAYING_PHONE] = "休息好了就继续吧~",
    [AWAY]          = "等你回来哦~",
    [DROWSY]        = "要不要起来活动一下?",
};

/* ==================== 模式配置表实现 ==================== */

mode_config_t g_mode_configs[2] = {
    [MODE_STRICT] = {
        .phone_glance_sec     = 8,
        .phone_playing_sec    = 8,
        .away_threshold_sec   = 10,
