343	static void *ui_worker(void *argument)
344	{
345	  unsigned int observed_generation = 0;
346	  (void)argument;
347	
348	  for (;;)
349	    {
350	      uint64_t elapsed;
351	      pthread_mutex_lock(&g_ui.lock);
352	      while (!g_ui.message_active)
353	        {
354	          pthread_cond_wait(&g_ui.wake, &g_ui.lock);
355	        }
356	      observed_generation = g_ui.message_generation;
357	      elapsed = monotonic_ms() - g_ui.message_started_ms;
358	      if (elapsed >= UI_MESSAGE_DURATION_MS)
359	        {
360	          if (observed_generation == g_ui.message_generation)
361	            {
362	              g_ui.message_active = 0;
363	              if (g_ui.screen == UI_SCREEN_REPORT) render_report_locked();
364	              else render_status_locked();
365	              present_locked();
366	            }
367	          pthread_mutex_unlock(&g_ui.lock);
368	          continue;
369	        }
370	
371	      render_message_locked(elapsed);
372	      present_locked();
373	      pthread_mutex_unlock(&g_ui.lock);
374	      sleep_ms(UI_ANIMATION_STEP_MS);
375	    }
376	
377	  return NULL;
378	}
