```c
// 状态机内部状态
static device_status_t g_state;
static int g_mode;              // MODE_STRICT / MODE_GENTLE
static bool g_paused;
static session_stats_t g_stats;
static uint8_t g_distraction_by_type[DIST_TYPE_COUNT];

// 时间基准
static uint64_t g_session_start_ms;   // 会话开始（真实时钟）
static uint64_t g_last_update_ms;     // 上次统计更新时间
static uint64_t g_accumulated_ms;     // 累计（暂停期间不累加）
static uint32_t g_last_remind_ms;     // 上次提醒时间（冷却用，但冷却在 behavior 里处理）

// 评分累计
static int g_score_accumulator;       // 专注评分累计

void state_machine_init(void) {
    g_state = DEVICE_IDLE;
    g_mode = MODE_STRICT;
    g_paused = false;
    memset(&g_stats, 0, sizeof(g_stats));
    memset(g_distraction_by_type, 0, sizeof(g_distraction_by_type));
    g_score_accumulator = 100;  // 起始 100 分
}

// 内部：开始会话
static void start_session(void) {
    memset(&g_stats, 0, sizeof(g_stats));
    memset(g_distraction_by_type, 0, sizeof(g_distraction_by_type));
    g_stats.current_mode = g_mode;
    g_stats.session_start = now_ms();
    g_score_accumulator = 100;
    g_session_start_ms = now_ms();
    g_last_update_ms = now_ms();
}

// 内部：切换模式
static void toggle_mode(void) {
    g_mode = (g_mode == MODE_STRICT) ? MODE_GENTLE : MODE_STRICT;
    behavior_set_mode(g_mode);  // 通知行为模块
    g_stats.current_mode = g_mode;
}

// 内部：处理 study_state
static void process_study_state(const study_state_t *ss) {
    // 1. 更新有效时长
    // 2. 更新评分（累加 focus_score_delta）
    // 3. 更新分心计数 + 类型
    // 4. 触发提醒/鼓励（调 audio + ui）
}

void state_machine_tick(void) {
    button_event_t btn = button_get_event();
    uint64_t now = now_ms();

    // 计算 elapsed（暂停期间不计）
    if (g_state == DEVICE_MONITORING && !g_paused) {
        uint32_t elapsed = (now - g_last_update_ms) / 1000;
        g_stats.total_duration_sec += elapsed;
        // effective 由 study_state 决定（FOCUSED 才加）
        g_last_update_ms = now;
    }

    // FSM 转移
    switch (g_state) {
    case DEVICE_IDLE:
        if (btn == BTN_START_LONGPRESS) {
            g_state = DEVICE_MODE_SELECT;
            // UI 更新
        }
        break;
    case DEVICE_MODE_SELECT:
        if (btn == BTN_MODE) {
            toggle_mode();
        } else if (btn == BTN_START_SHORT) {
            start_session();
            g_state = DEVICE_MONITORING;
        }
        break;
    case DEVICE_MONITORING:
        if (btn == BTN_PAUSE_SHORT) {
            g_paused = !g_paused;
        } else if (btn == BTN_PAUSE_LONGPRESS || btn == BTN_STOP) {
            end_session();
            g_state = DEVICE_REPORT;
        }
        if (!g_paused) {
            study_state_t ss = behavior_analyze();
            process_study_state(&ss);
        }
        break;
    case DEVICE_REPORT:
        if (btn == BTN_START_SHORT) {
            reset_session();
            g_state = DEVICE_IDLE;
        }
        break;
    }

    // UI 刷新
    ...
}
```

这个设计需要 now_ms() 函数（单调时钟）。

关于有效学习时长：规划里说 "FOCUSED 增加有效学习时长"。所以 effective_duration 只在 study_state.status == FOCUSED 时累加。但更精确的做法是：每 tick 计算 elapsed，如果当前是 FOCUSED 状态，就加到 effective。

不过 behavior_analyze 每次 tick 都调用，返回的 status 是"当前状态"。所以逻辑是：
- total_duration += elapsed（总是）
- if (ss.status == FOCUSED) effective_duration += elapsed

