int main(int argc, char *argv[]) {
    // banner
    init_modules();
    state_machine_init();

    printf("[core] 进入主循环 (state_machine_tick @ 10Hz)...\n");

    // 主循环
    while (1) {
        state_machine_tick();
        usleep(100000);  // 100ms
    }
    return 0;
