    printf("  观测序列: %d 帧\n", FAKE_COUNT);
    printf("==================================================\n\n");

    int frame_interval = 5;  /* 每 5 秒一帧 */
    int mode_ticks     = 120; /* 跑 120 tick = 10 分钟 (每秒 1 tick) */

    for (tick = 0; tick < mode_ticks; tick++)
    {
        /* ---- camera_task: 每 frame_interval 秒产一帧 ---- */
        if (tick % frame_interval == 0)
