```c
static int mimo_detect(uint8_t *jpeg, size_t jpeg_len, cloud_result_t *raw)
{
    /* 1. Base64 编码 + 前缀 */
    size_t b64_cap = perception_base64_encoded_len(jpeg_len) + 1;
    char *b64 = malloc(b64_cap);
    if (!b64) return FOCUS_ERR_PERCEP_PARAM;
    size_t b64_len = perception_base64_encode(jpeg, jpeg_len, b64, b64_cap);
    if (b64_len == 0) { free(b64); return FOCUS_ERR_PERCEP_PARAM; }

    /* 2. OpenAI chat/completions 请求体 (图片 base64 + prompt) */
    /* data:image/jpeg;base64,<b64> 前缀 + image_url */
    size_t img_len = strlen("data:image/jpeg;base64,") + b64_len;
    char *img = malloc(img_len + 1);
    snprintf(img, img_len + 1, "data:image/jpeg;base64,%s", b64);
    free(b64);

    /* JSON 请求: 构造含 image_url + text 的 messages */
    /* 用 snprintf 构造 (cJSON 生成更安全, 但简单场景 snprintf) */
    size_t req_cap = img_len + 512;
    char *req = malloc(req_cap);
    ...
    snprintf(req, req_cap,
      "{\"model\":\"mimo-v2.5\",\"max_completion_tokens\":800,"
      "\"messages\":["
      "{\"role\":\"system\",\"content\":\"You are MiMo...\"},"
      "{\"role\":\"user\",\"content\":["
      "{\"type\":\"image_url\",\"image_url\":{\"url\":\"%s\"}},"
      "{\"type\":\"text\",\"text\":\"%s\"}]}]}",
      img, MIMO_PROMPT);
    free(img);

    /* 3. POST (重试 1 次) */
    int ret = wifi_http_post(g_api_url, req, g_resp, sizeof(g_resp));
    if (ret < 0) ret = wifi_http_post(...);
    free(req);
    if (ret < 0) return FOCUS_ERR_PERCEP_TIMEOUT;

    /* 4. 解析 */
    return perception_parse_cloud_response(g_resp, raw);
}
