int perception_parse_cloud_response(const char *resp, cloud_result_t *out)
{
    /* 1. 解析外层 OpenAI 响应 */
    cJSON *root = cJSON_Parse(resp);
    if (!root) return JSON;
    cJSON *choices = cJSON_GetObjectItem(root, "choices");
    if (!cJSON_IsArray(choices) || cJSON_GetArraySize(choices) == 0) { delete; return NODATA; }
    cJSON *msg = cJSON_GetObjectItem(cJSON_GetArrayItem(choices, 0), "message");
    cJSON *content = cJSON_GetObjectItem(msg, "content");
    if (!cJSON_IsString(content)) { delete; return NODATA; }

    /* 2. content 是 JSON 字符串, 提取 JSON 对象 (找第一个 { 到最后一个 }) */
    const char *s = content->valuestring;
    const char *start = strchr(s, '{');
    const char *end = strrchr(s, '}');
    if (!start || !end || end <= start) { delete; return JSON; }

    /* 3. 解析内层 JSON → cloud_result_t */
    char buf[512];
    size_t len = end - start + 1;
    if (len >= sizeof(buf)) len = sizeof(buf) - 1;
    memcpy(buf, start, len); buf[len] = 0;
    cJSON *inner = cJSON_Parse(buf);
    ...填充 out...
    cJSON_Delete(inner); cJSON_Delete(root);
    return OK;
}
