// rgb565_jpeg.c
#define TJE_IMPLEMENTATION
#include "../third_party/tiny_jpeg.h"
#include "rgb565_jpeg.h"

/* JPEG 输出回调 (收集编码数据) */
typedef struct {
    uint8_t *buf;
    size_t cap;
    size_t used;
} jpeg_sink_t;

static void jpeg_write_cb(void *ctx, void *data, int size)
{
    jpeg_sink_t *sink = (jpeg_sink_t *)ctx;
    if (sink->used + size <= sink->cap) {
        memcpy(sink->buf + sink->used, data, size);
        sink->used += size;
    }
}

int rgb565_to_jpeg(const uint8_t *rgb565, int width, int height,
                   uint8_t *jpeg_out, size_t *jpeg_size)
{
    if (!rgb565 || !jpeg_out || !jpeg_size || width<=0 || height<=0) return -1;
    /* RGB565 → RGB888 临时缓冲 */
    uint8_t *rgb = malloc(width*height*3);
    if (!rgb) return -1;
    for (int i=0; i<width*height; i++) {
        uint16_t p = (rgb565[i*2]) | (rgb565[i*2+1] << 8);
        uint8_t r5 = (p >> 11) & 0x1F;
        uint8_t g6 = (p >> 5) & 0x3F;
        uint8_t b5 = p & 0x1F;
        rgb[i*3]   = (r5 << 3) | (r5 >> 2);
        rgb[i*3+1] = (g6 << 2) | (g6 >> 4);
        rgb[i*3+2] = (b5 << 3) | (b5 >> 2);
    }
    jpeg_sink_t sink = { jpeg_out, *jpeg_size, 0 };
    int ok = tje_encode_with_func(jpeg_write_cb, &sink, 2, width, height, 3, rgb);
    free(rgb);
    if (!ok) return -1;
    *jpeg_size = sink.used;
    return 0;
}
