688	                               imgdata_format_t *datafmts,
689	                               imgdata_interval_t *interval,
690	                               imgdata_capture_t callback,
691	                               void *arg)
692	{
693	  struct esp32s3_cam_s *priv = (struct esp32s3_cam_s *)data;
694	  uint32_t regval;
695	
696	  if (priv->capturing)
697	    {
698	      return -EBUSY;
699	    }
700	
701	  if (!priv->fb)
702	    {
703	      return -EINVAL;
704	    }
705	
706	  priv->cb = callback;
707	  priv->cb_arg = arg;
708	  priv->fb_pos = 0;
709	  priv->vsync_cnt = 0;
710	  priv->dma_received = 0;
711	  priv->dma_desc_offset = 0;
712	
713	  memset(priv->fb, 0, priv->fb_alloc);
714	
715	  /* Rebuild DMA descriptors (reset OWN bits consumed by prior DMA) */
716	
717	  esp32s3_cam_setup_dma(priv);
718	
719	  up_clean_dcache((uintptr_t)priv->fb,
720	                  (uintptr_t)priv->fb + priv->fb_alloc);
721	
722	  /* Stop CAM first */
723	
724	  regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
725	  regval &= ~LCD_CAM_CAM_START_M;
726	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
727	
728	  /* Reset CAM module + AFIFO */
729	
730	  regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
731	  regval |= LCD_CAM_CAM_RESET_M;
732	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
733	  regval &= ~LCD_CAM_CAM_RESET_M;
734	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
735	
736	  regval |= LCD_CAM_CAM_AFIFO_RESET_M;
737	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
738	  regval &= ~LCD_CAM_CAM_AFIFO_RESET_M;
739	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
740	
741	  /* Reset DMA channel */
742	
743	  esp32s3_dma_reset_channel(priv->dma_channel, false);
744	
745	  /* Load DMA descriptors */
746	
747	  esp32s3_dma_load(priv->dmadesc, priv->dma_channel, false);
748	  esp32s3_dma_enable(priv->dma_channel, false);
749	
750	  /* cam_update BEFORE cam_start */
751	
752	  regval = getreg32(LCD_CAM_CAM_CTRL_REG);
753	  regval |= LCD_CAM_CAM_UPDATE_REG_M;
754	  putreg32(regval, LCD_CAM_CAM_CTRL_REG);
755	
756	  regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
757	  regval |= LCD_CAM_CAM_START_M;
758	  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
759	
760	  priv->capturing = true;
761	
762	  esp32s3_gpio_matrix_in(CONFIG_ESP32S3_CAM_VSYNC_PIN,
763	                         CAM_V_SYNC_IDX, false);
764	  up_udelay(10);
765	  esp32s3_gpio_matrix_in(CONFIG_ESP32S3_CAM_VSYNC_PIN,
766	                         CAM_V_SYNC_IDX, true);
767	
768	  return OK;
769	}
