                    content_type="text/html; charset=utf-8")
    elif path == "/preview.jpg":
        self._serve_preview_jpeg()
    elif path == "/report":
        self._reply(200, REPORT_PAGE.encode(),
                    content_type="text/html; charset=utf-8")
    elif path == "/report.json":
        self._serve_report_json()
