 * 导致 CPU1 崩溃 (EPC1=0, 栈被高熵数据填满)。改为一次性大缓冲,
 * 彻底消除每帧堆抖动。 */
#define DETECT_SCRATCH_BYTES  (512 * 1024)   /* 够放 base64 + img + req */

static char  *g_scratch;
static size_t g_scratch_cap;

static char *scratch_alloc(size_t need)
{
    if (g_scratch != NULL && g_scratch_cap >= need) {
        return g_scratch;
    }
    free(g_scratch);
    g_scratch = malloc(need);
    g_scratch_cap = (g_scratch != NULL) ? need : 0;
    return g_scratch;
}

