TX_CHUNK = 64
TX_GAP = 0.004


def paced_write(ser, data):
    """分块写入串口, 每块后短暂让出, 避免接收端丢数据。"""
    for i in range(0, len(data), TX_CHUNK):
        ser.write(data[i:i + TX_CHUNK])
        ser.flush()
        if i + TX_CHUNK < len(data):
            time.sleep(TX_GAP)

